    //获取url里面的参数
    public static getQueryString(name: string): any {
        var reg = new RegExp("(^|&)" + name + "=([^&]*)(&|$)");
        var r = window.location.search.substr(1).match(reg);
        if (r != null) return r[2]; //注意这里不能用js里面的unescape方法
        return "";
    }

    public static getInviteWalletAddress() {
        let url = this.getQueryString("invite");
        if (url) {
            url = this.decode(url);
        }
        return url;
    }

    public static toWei(value: number, decimals: string) {
        let num = value * 10 ** parseInt(decimals);
        let tokens = (window as any)["web3"].utils.toBN("0x" + num.toString(16));
        return tokens.toString();
    }

    public static fromWei(value: string | any[], decimals: number, point = 0) {
        if (!value) {
            return 0;
        }
        let len = value.length - decimals + point;
        if (len <= 0) {
            return 0;
        }
        let temp = value.toString().slice(0, len);
        if (point) {
            let tt = temp.length - point;
            if (tt <= 0) {
                let ttt = "0.";
                for (let index = 0; index < Math.abs(tt); index++) {
                    ttt += "0";
                }
                temp = ttt + temp;
            } else {
                temp = temp.slice(0, temp.length - point) + "." + temp.slice(temp.length - point);
            }
        }
        return temp;
    }

    public static deepClone(obj: any): Dictionary {
        let temp: any = new Dictionary();
        for (let k in obj) {
            if (typeof obj[k] == "function") {
                //如果是方法直接赋值就可以了
                temp[k] = obj[k];
            } else {
                temp[k] = JSON.parse(JSON.stringify(obj[k]));
            }
        }
        return temp;
    }

    public static signTelegramArray(code: string) {
        let codes = code.split("&"); // 分割各个签名组件
        // 分解签名组件
        let type = codes[6];	// web3 type=1, telegram type=2, telegram evm type=3
    
        if (type === "2") {
            // telegram Login
            let timestamp = parseFloat(codes[0]);	// 时间戳
            let randomHex = codes[1];	// 随机哈希
            let signatureHex = codes[2];	// 签名值
            let domain = codes[3];	// 域名
            let publicKey = codes[4];	// 公钥
            let address = codes[5];
    
            const loginData = {
                timestamp,
                randomHex,
                signatureHex,
                domain,
                publicKey,
                address,
                type,
            }
    
            return loginData
        } else {
            // Visitor Login
            let time = parseFloat(codes[0]); // 时间戳
            let randomHex = codes[1]; // 随机哈希
            let r = codes[2]; // 签名r值
            let s = codes[3]; // 签名s值
            let v = codes[4]; // 签名v值
            let address = codes[5];
            const loginData = {
                time,
                randomHex,
                r,
                s,
                v,
                address,
                type,
            }
    
            return loginData
        }
    }

    public static changeTonAddress(account: any) {
        ConfigBuilder;
        if (account) {
            const address = Address.parse(account);
            // Non-bounceable 地址（UQ 开头）
            const reallyAddress = address.toString({ bounceable: false, urlSafe: true });
            return reallyAddress;
        }
    }
    
    /**
     * 将非弹跳地址转换回原始TON地址
     * @param nonBounceableAddress 非弹跳格式的地址
     * @returns 原始TON地址
     */
    public static revertTonAddress(tonAddress: string) {
        if (tonAddress) {
            try {
                // 解析TON地址
                const address = Address.parse(tonAddress);
                
                // 获取workchain id和十六进制地址
                const workchain = address.workChain;
                const hexAddress = address.hash.toString('hex');
                
                // 转换为原始格式：workchain:hex_address
                const originalAddress = `${workchain}:${hexAddress}`;
                
                console.log(`转换地址: ${tonAddress} -> ${originalAddress}`);
                return originalAddress;
            } catch (error) {
                console.error("TON地址转换失败:", error);
                return tonAddress; // 转换失败时返回原地址
            }
        }
        return tonAddress;
    }
