const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import SheetDataManager from "../../global/SheetDataManager";
import { ComUtil } from "../../utils/ComUtil";
import { TimeUtil } from "../../utils/TimeUtil";
import { ReferralListItemBase } from "./ReferralListItem.generated";

@regClass('UE9rYjENQbOU+0ZTLzyHGw==')
export class ReferralListItem extends ReferralListItemBase {
    public constructor() {
        super();
    }

    private referralData: any;

    public createChildren(): void {
        super.createChildren();
    }

    onEnable(): void {}

    public set dataSource(value: any) {
        if (!value) return;

        super.dataSource = value;
        this.referralData = value;

        // 定义接口类型
        interface ReferralData {
            headId: string;
            nickName: string;
            country: number;
            online: string | number;
            level: number;
        }

        // 解构数据
        const [headId, nickName, , country, level, online] = value.split(",");
        const referralData: ReferralData = {
            headId,
            nickName,
            country: Number(country),
            online,
            level
        };

        // 更新UI显示
        this.tf_name.text = referralData.nickName;
        this.playerIcon.headSkin = referralData.headId;

        // 获取并显示国家信息
        const countryItem = SheetDataManager.m_dicCountry.get(referralData.country);
        if (countryItem) {
            this.img_country.skin = GameResourceManager.getCountryIcon(countryItem.icon);
            this.tf_country.text = ComUtil.truncateString(GameLanguageMgr.getLanguage(countryItem.name), 9);
        }

        // 显示战斗信息
        this.tf_level.text = `${referralData.level}`;

        // 处理在线状态显示
        const isOnline = referralData.online === "0";
        this.tf_online.text = isOnline ? "online" : TimeUtil.formatTimeAgoFromTimestamp(Number(referralData.online));
        this.tf_online.color = isOnline ? "#12f801" : "#ffffff";
    }

    onBtn12() {
        if (this.referralData.remNum > 0) {
            ModuleManager.intance.openModule(ModuleName.ReferralL2Dialog, this.referralData);
        }
    }
}
