const { regClass } = Laya;
import { WithdrawDialogBase } from "./WithdrawDialog.generated";
import { TokenData } from "../../data/dto/TokenData";
import Signal from "../../global/event/Signal";
import { com } from "../../network/pb/socket";
import HallWebSocket from "../../network/HallWebSocket";
import { LayerManager } from "../../common/LayerManager";
import { WithDrawDto } from "../../data/dto/DepositDto";
import { ComUtil } from "../../utils/ComUtil";
import { GameEvent } from "../../global/event/GameEvent";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import LoadingManager from "../../common/LoadingManager";
import EthereumManager from "../../global/contract/EthereumManager";
import NoticeMgr from "../notice/NoticeMgr";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import GameResourceManager from "../../common/GameResourceManager";
import { NumberUtil } from "../../utils/NumberUtil";
import GameSetting from "../../global/GameSetting";

@regClass('+G96ocIBRFacV4Xozyt5NQ==')
export class WithdrawDialog extends WithdrawDialogBase {
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private data: TokenData;
    private btnLock: boolean = false; //按钮防止连点锁
    private withDrawData: WithDrawDto = null;
    private withdrawText: string = null;
    private address: string;
    private withdrawAddress: string;
    private realTokenData: any;
    private appAmount: number;

    public constructor() {
        super();
    }

    onEnable(): void {
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_WITHDRAW, this, this.onRequestWithdraw);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_WITHDRAW_INFO, this, this.onRequestChargeInfo);
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_WITHDRAW_LIST, this, this.onRequestWithdrawList);
        Signal.on(GameEvent.UPDATE_TOKEN_BALANCE, this, this.onTokenBalanceUpdate);
        // 列表渲染和选择处理
        this.list_token.renderHandler = Laya.Handler.create(this, this.onTokenItemRender, null, false);
        this.list_token.selectHandler = new Laya.Handler(this, this.handleSelectToken);
        this.img_di1.on(Laya.Event.CLICK, this, this.onCheakTab);
        this.btn_withdraw.on(Laya.Event.CLICK, this, this.onBtnWithdraw);
        this.withdrawText = this.withdrawCode.prompt;
        this.withdrawCode.on(Laya.Event.INPUT, this, this.testRechargeCodeInput);
        this.withdrawCode.on(Laya.Event.FOCUS, this, this.onInputFocus);
        this.withdrawCode.on(Laya.Event.BLUR, this, this.onInputBlur);
        this.btn_max.on(Laya.Event.CLICK, this, this.onBtnMax);
        this.btn_changeAddress.on(Laya.Event.CLICK, this, this.onBtnChangeAddress);
        this.btn_confirm.on(Laya.Event.CLICK, this, this.confirmAddress);
        this.btn_hideBox.on(Laya.Event.CLICK, this, this.onCloseTab);
        this.btn_help.on(Laya.Event.CLICK, this, this.onBtnHelp);
        this.address = EthereumManager.walletAddress;
        this.withdrawAddress = EthereumManager.walletAddress;
        // 初始化时设置字体大小
        this.updateFontSize(false);
    }

    public setOpenData(data: any) {
        this.data = data;
        this.showWithDrawData(data);
        this.getWithdrawList(data.symbol);
        this.alertTitle.text = GameLanguageMgr.getLanguage(89, data.symbol);
        // this.requestChargeInfo();
        console.log("data", data);
    }

    /**
     * 显示提币内容
     * @param data
     */
    private async showWithDrawData(data: TokenData) {
        let account = EthereumManager.walletAddress;
        // this.tf_address.text = ComUtil.shortenString(account, 6, 4);
        this.tf_address.text = account;
        this.tf_token.text = data.symbol;    
        this.tf_web.text = data.chainName;
        this.tf_appAmount.text = `${NumberUtil.formatTrimZeroDecimal2(data.balance,5)} ${data.symbol}`;
        this.appAmount = data.balance;
    }

    /**
     * 请求资产信息
     */
    private requestChargeInfo(symbolId: number): void {
        const cmdId = com.snake.socket.MessageType.MSG_WITHDRAW_INFO;
        // const symbolId = symbolId;
        const requestData = com.snake.socket.CS_WITHDRAW_INFO.fromObject({
            symbolId: symbolId
        });
        HallWebSocket.send(cmdId, requestData);
    }

    /**
     * 提币点击
     * @returns
     */
    private async onBtnWithdraw() {
        // 防止连点
        console.log(this.realTokenData)
        if (this.btnLock) {
            return;
        } else {
            this.btnLock = true;
            Laya.timer.once(2000, this, () => {
                this.btnLock = false;
            });
        }

        if (this.changeNameBox.visible) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(84));
            return
        }

        // 验证提币码输入,防止输入非数字
        this.testWithdrawCodeInput();
        const withdrawNum = Number(this.withdrawCode.text);
        if (!withdrawNum) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(63));
            return;
        }
        if (this.withdrawAddress.trim() == "") {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(85));
            return;
        }

        // 验证提现金额是否超过可用余额
        if (withdrawNum > this.appAmount) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(64));
            return;
        }

        // 验证提现金额是否超过最大限额
        if (withdrawNum > this.withDrawData.maxLimit) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(65));
            return;
            // 验证提现金额是否低于最小限额
        } else if (withdrawNum < this.withDrawData.minLimit) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(66));
            return;
        }

        let todayWithdrawVal = this.data.totalWithdraw;
        let todayMax = this.withDrawData.todayAmount;
        if((todayWithdrawVal + withdrawNum) > todayMax){
            NoticeMgr.notice(GameLanguageMgr.getLanguage(91));//超过今日提币上限
            return
        }

        // 增加加载页
        LoadingManager.showLoadingByInfo();

        // 发送提币请求
        const cmdId = com.snake.socket.MessageType.MSG_WITHDRAW;
        const requestData = com.snake.socket.CS_WITHDRAW.fromObject({
            symbolId: this.realTokenData.symbolId,
            amount: withdrawNum,
            toAddress: this.withdrawAddress
        });
        HallWebSocket.send(cmdId, requestData);
    }

    /**
     * 提币回调
     */
    public onRequestWithdraw(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_WITHDRAW = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_WITHDRAW);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(67));
            // console.log("SC_WITHDRAW MsgBody", msgBody);
            // const resp = JSON.parse(msgBody.resp);
            // console.log("resp", resp);
            LoadingManager.hideLoading();
            // 发送资产更新事件
            Signal.event(GameEvent.UPDATE_ASSETS);
            this.close()
            // this.close();
        }
    }

    /**
     * 提币输入
     */
    private async onRechargewithdrawCodeInput() {
        let number = Number(this.withdrawCode.text);
        const isNumber = ComUtil.isNumber(this.withdrawCode.text);
        if ((number < 0 || !isNumber) && this.withdrawCode.text !== this.withdrawText) {
            this.withdrawCode.text = `0`;
        }

        // 计算手续费
        let feeNum = ComUtil.multiplyWithPrecision(this.withDrawData.feeRate / 100, number);
        // this.tf_fee.text = `${this.withDrawData.feeRate/100}%`;
        this.tf_arrive.text = `${ComUtil.subtractWithPrecision(number, Number(feeNum))} ${this.data.symbol}`;
    }

    /**
     * 验证提币码输入
     */
    private testWithdrawCodeInput(): void {
        const value = this.withdrawCode.text;
        if (value) {
            const reg = /^[0-9]+\.?[0-9]*$/;
            if (!reg.test(value)) {
                this.withdrawCode.text = "";
                NoticeMgr.notice(GameLanguageMgr.getLanguage(1802));
                return;
            }
        }
    }

    public onRequestChargeInfo(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_WITHDRAW_INFO = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_WITHDRAW_INFO);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            console.log("CS_WITHDRAW_INFO", msgBody);
            //解析参数
            let resp = JSON.parse(msgBody.resp);
            if (msgBody.resp) {
                this.withDrawData = resp;
                console.log("resp", resp);
                //获取到提币信息
                this.showWithdrawData2();
            }
        }
    }

    private async showWithdrawData2() {
        this.img_icon.skin = GameResourceManager.getChainIcon(this.withDrawData.chainId);
        this.tf_fee.text = `${this.withDrawData.feeRate}%`;
        this.withdrawCode.prompt = GameLanguageMgr.getLanguage(87, this.withDrawData.minLimit, this.data.symbol);
        this.withdrawText = this.withdrawCode.prompt;
    }

    onDisable(): void {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_WITHDRAW, this, this.onRequestWithdraw);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_WITHDRAW_INFO, this, this.onRequestChargeInfo);
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_WITHDRAW_LIST, this, this.onRequestWithdrawList);
        Signal.off(GameEvent.UPDATE_TOKEN_BALANCE, this, this.onTokenBalanceUpdate);
        this.withdrawCode.off(Laya.Event.INPUT, this, this.onRechargewithdrawCodeInput);
        this.withdrawCode.off(Laya.Event.INPUT, this, this.testRechargeCodeInput);
        this.withdrawCode.off(Laya.Event.FOCUS, this, this.onInputFocus);
        this.withdrawCode.off(Laya.Event.BLUR, this, this.onInputBlur);
        this.btn_withdraw.off(Laya.Event.CLICK, this, this.onBtnWithdraw);
        this.btn_max.off(Laya.Event.CLICK, this, this.onBtnMax);
        this.btn_changeAddress.off(Laya.Event.CLICK, this, this.onBtnChangeAddress);
        this.btn_confirm.off(Laya.Event.CLICK, this, this.confirmAddress);
        this.btn_hideBox.off(Laya.Event.CLICK, this, this.onCloseTab);
        this.img_di1.off(Laya.Event.CLICK, this, this.onCheakTab);
    }

    /**
     * 更新当前币种余额
     * @param tokenData 所有币种余额数据
     */
    private onTokenBalanceUpdate(tokenData: TokenData[]): void {
        if (!this.data || !tokenData) return;
        const currentToken = tokenData.find((token) => token.symbolId === this.data.symbolId);
        if (currentToken) {
            this.data.balance = currentToken.balance;
            this.tf_appAmount.text = `${currentToken.balance}`;
        }
    }

    /**
     * 验证充值码输入
     * 限制只能输入数字和小数点，且只能输入正数
     */
    private testRechargeCodeInput(): void {
        const value = this.withdrawCode.text;
        if (value) {
            // 正则表达式验证：只允许输入正数（整数或小数）
            const reg = /^[0-9]+\.?[0-9]*$/;
            // 检查是否为负数或非法字符
            if (!reg.test(value)) {
                // 过滤掉非法字符，只保留数字和小数点
                let filteredValue = "";
                for (let i = 0; i < value.length; i++) {
                    const char = value.charAt(i);
                    if ((char >= "0" && char <= "9") || (char === "." && filteredValue.indexOf(".") === -1)) {
                        filteredValue += char;
                    }
                }

                // 更新输入框内容
                this.withdrawCode.text = filteredValue;

                // 如果内容被修改，显示提示信息
                // if (filteredValue !== value) {
                //     NoticeMgr.notice(GameLanguageMgr.getLanguage(1802));
                // }
            }

            // 确保不是0开头的多位数（除非是小数）
            if (value.length > 1 && value.startsWith("0") && value.charAt(1) !== ".") {
                this.withdrawCode.text = value.substring(1);
            }
        }
        let number = Number(this.withdrawCode.text);
        // 计算手续费
        let feeNum = ComUtil.multiplyWithPrecision(this.withDrawData.feeRate / 100, number);
        // this.tf_fee.text = `${this.withDrawData.feeRate/100}%`;
        this.tf_arrive.text = `${ComUtil.subtractWithPrecision(number, Number(feeNum))} ${this.data.symbol}`;

        // 更新字体大小
        this.updateFontSize(false);
        // 新增：根据输入内容显示或隐藏img_dataBottom
        // if (this.withdrawCode.text && this.withdrawCode.text !== this.withdrawText) {
        //     this.img_dataBottom.visible = true;
        // } else {
        //     this.img_dataBottom.visible = false;
        // }
    }

    private onBtnMax(): void {
        let todayWithdrawVal = this.data.totalWithdraw;
        let todayMax = this.withDrawData.todayAmount;
        // let maxNum = todayMax - todayWithdrawVal;
        let maxNum = Number(ComUtil.subtractWithPrecision(todayMax, todayWithdrawVal));
        let showNum = Math.min(this.data.balance,this.withDrawData.maxLimit,maxNum)
        this.withdrawCode.text = `${showNum}`;
        // this.img_dataBottom.visible = true;
        this.onRechargewithdrawCodeInput()
        // 更新字体大小
        this.updateFontSize(false);
    }

    /**
     * 输入框获得焦点
     */
    private onInputFocus(): void {
        // 获得焦点时立即设置为大字体
        this.withdrawCode.fontSize = 38;
    }

    /**
     * 输入框失去焦点
     */
    private onInputBlur(): void {
        this.updateFontSize(false);
    }

    /**
     * 更新输入框字体大小
     * 如果显示提示文字，设置为22
     * 如果是输入的文字，设置为38
     * @param hasFocus 是否处于焦点状态
     */
    private updateFontSize(hasFocus: boolean = false): void {
        if (!this.withdrawCode) return;

        // 判断是否显示提示文字
        const isEmpty = this.withdrawCode.text === "" || this.withdrawCode.text === this.withdrawText;

        // 设置字体大小
        if (isEmpty && !hasFocus) {
            this.withdrawCode.fontSize = 30;
        } else {
            this.withdrawCode.fontSize = 38;
        }
    }

    private onBtnChangeAddress(): void {
        this.tf_address.visible = false;
        this.changeNameBox.visible = true;
        this.btn_changeAddress.visible = false;
        this.input_name.text = "";
    }

    private confirmAddress(): void {
        this.address = this.input_name.text;
        this.withdrawAddress = this.address;
        this.tf_address.text = this.input_name.text;
        this.tf_address.visible = true;
        this.changeNameBox.visible = false;
        this.btn_changeAddress.visible = true;
    }

    private getWithdrawList(symbol: string) {
        const cmdId = com.snake.socket.MessageType.MSG_WITHDRAW_LIST;
        const requestData = com.snake.socket.CS_WITHDRAW_LIST.fromObject({
            symbol: symbol
        });
        HallWebSocket.send(cmdId, requestData);
    }

    /**
     * 提币列表回调
     */
    public onRequestWithdrawList(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            var msgBody: com.snake.socket.SC_WITHDRAW_LIST = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_WITHDRAW_LIST);
            let withdrawList = msgBody.info || [];
            // 这里可以根据需要刷新UI，例如：this.updateWithdrawListUI();
            console.log("提币列表：", withdrawList);
            let data = ComUtil.parseJsonArray(withdrawList);
            this.dealWithdrawList(data);
        } else {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(1803)); // 假设1803为获取提币列表失败
        }
    }

    private async dealWithdrawList(data: any[]) {
        let filteredData = data;
        let tonConnectUI = EthereumManager.tonConnectUI;
        if(!EthereumManager.isTronLogin){
            // 非Tron登录状态下，过滤掉chainName为"Tron Mainnet"的项目
            filteredData = data.filter((item: any) => item.chainName !== "Tron Mainnet" && item.chainName !== "TRON-TEST");
        }
        if(!tonConnectUI){
            filteredData = data.filter((item: any) => item.chainName !== "TON");
        }
        this.list_token.array = filteredData;
        this.list_token.selectedIndex = 0;
        console.log("tonConnectUI", tonConnectUI);
        if (!tonConnectUI) {
            this.list_token.selectedIndex = 0;
        }else{

        }
        if(tonConnectUI){
            let index = this.list_token.array.findIndex((item:any)=>item.chainName == "TON");
            if(index != -1){
                this.list_token.selectedIndex = index;
                this.img_di1.mouseEnabled = false;
            }
        }else if(EthereumManager.isTronLogin){
            let chainName = GameSetting.vType == 2?"Tron Mainnet":"TRON-TEST"
            let index = this.list_token.array.findIndex((item:any)=>item.chainName == chainName);
            if(index != -1){
                this.list_token.selectedIndex = index;
                this.img_di1.mouseEnabled = false;
            }
        }

    }

    /**
    * 显示代币选择面板
    */
    private onCheakTab(): void {
        if (!this.img_token_pad.visible) {
            this.img_token_pad.visible = true;
            this.btn_hideBox.visible = true;
        }
    }

    /**
     * 关闭代币选择面板
     */
    private onCloseTab(): void {
        if (this.img_token_pad.visible) {
            this.btn_hideBox.visible = false;
            this.img_token_pad.visible = false;
        }
    }

    /**
   * 列表项渲染处理
   */
    private onTokenItemRender(cell: any, index: number): void {
        if (cell && cell.onChange) {
            cell.onChange(this.list_token.selectedIndex == index);
            // this.img_token_pad.visible = false;
            // this.btn_hideBox.visible = false;
        }
    }

    /**
     * 代币选择处理
     */
    private handleSelectToken(index: number): void {
        this.img_token_pad.visible = false;
        this.btn_hideBox.visible = false;
        if (index != -1) {
            this.updateTokenInfo(index);
        }
    }

    /**
   * 更新代币信息显示
   * @param roomItem 房间项
   */
    private updateTokenInfo(index: number): void {
        if (!this.list_token) return
        // this.webIndex = index;
        const tokenData = this.list_token.array[index];
        this.realTokenData = tokenData;
        console.log(this.realTokenData)
        if (tokenData) {
            this.tf_web.text = tokenData.chainName;
            this.setNetAndToken()
            // this.tf_coin.text = tokenData.symbol;
            // this.img_coin.skin = GameResourceManager.getCurrencyIcon(this.roomData.ticketType[index]);
            // this.tf_number.text = String(this.roomData.ticketAmount[index]);
        }
    }

    private setNetAndToken() {
        // 获取匹配项的下标
        // if (!matchedItem) {
        //     console.log("未找到匹配的链信息");
        //     return;
        // }
        // console.log("匹配项：", this.realTokenData, "下标：", matchedIndex);
        this.tf_web.text = this.realTokenData.chainName;
        this.tf_token.text = this.realTokenData.symbol;
        this.requestChargeInfo(this.realTokenData.symbolId);
        this.tf_arrive.text = "-";
        // this.tf_appAmount.text = "";
        this.tf_fee.text = "-";
        this.withdrawCode.text = "";
        // this.img_dataBottom.visible = false;
    }

    private onBtnHelp(): void {
        // 打开服务条款网页
        window.open("https://drive.google.com/file/d/1ktcZ2P7lMKEJDsymetdqUzvWKbF0VR2n/view", "_blank");
    }
}
