    // 使用Tween进行放大缩小效果
    scaleEffect() {
        var that = this;
        // 缩放到1.3倍
        Laya.Tween.to(
            this.tf_reduceTime,
            { scaleX: 1.3, scaleY: 1.3 },
            200,
            Laya.Ease.linearInOut,
            Laya.Handler.create(this, function () {
                // 还原到原始大小
                Laya.Tween.to(that.tf_reduceTime, { scaleX: 1, scaleY: 1 }, 200, Laya.Ease.linearInOut);
            })
        );
    }

    private onGameSceneGray(): void {
        this.matchBox.gray = true;
        Laya.timer.once(1000, this, this.stopUpdate);
    }

    stopUpdate() {
        Laya.timer.clear(this, this.gameLoop);
        GameAiControl.endTimer(); //10秒后取消定时器
    }

    onEnable(): void {
        Signal.on(GameEvent.EVENT_GameScene_Gray, this, this.onGameSceneGray);
        Signal.on(GameEvent.EVENT_CLICK_SPACE, this, this.onSpaceClick);

        // 注册窗口获得焦点事件
        Laya.stage.on(Laya.Event.FOCUS, this, this.onWindowFocus);

        // 在游戏初始化代码中添加
        Laya.stage.on(Laya.Event.KEY_DOWN, this, this.onKeyDown);
    }

    onKeyDown(e: Laya.Event) {
        if (e.keyCode === Laya.Keyboard.X) {
            DebugLayer.getInstance().toggleVisible();
        }
    }

    onWindowFocus() {}

    onDisable(): void {
        this.stopUpdate();
        Signal.off(GameEvent.EVENT_GameScene_Gray, this, this.onGameSceneGray);
        Signal.off(GameEvent.EVENT_CLICK_SPACE, this, this.onSpaceClick);
        Laya.stage.off(Laya.Event.KEY_DOWN, this, this.onKeyDown);
        this.removeEvents();

        Laya.stage.off(Laya.Event.FOCUS, this, this.onWindowFocus);
        Laya.timer.clearAll(this);
        GameAiControl.clear();
        MatchModel.clearData();
    }
