import GameLanguageMgr from "../../../common/GameLanguageMgr";
import GameResourceManager from "../../../common/GameResourceManager";
import SheetDataManager from "../../../global/SheetDataManager";
import AssetManager from "../../../manager/AssetManager";
import { EnumItemType } from "../../enumData/EnumItemType";
import { ItemItem } from "../../sheetItem/item/ItemItem";

export class ItemVo {
    public constructor(__id: number = 0) {
        if (__id == 0) {
            return;
        }
        this.id = __id;
    }
    public m_iOriginalId: number;
    private _m_iId: number;

    private _m_iPk: string;
    private _m_iLevel: number = 0;
    public m_iExp: number;
    public m_bNew: boolean;
    private _m_bSet: boolean;
    public itemItem: ItemItem;

    public quality: number;
    public _m_arrDisc: any[] = [];
    public m_iPrice: number;
    public m_strBuyIcon: string;
    public m_iSellPrice: number;
    public m_strSellIcon: string;
    public newAddCnt: number = 0;
    public isScholarship: boolean = false;
    public isLvUp: boolean = false;
    public num: number;
    public type: number;
    public subType: number;
    public backType: number;

    public needTip: boolean = true;

    /**
     * 0=未上链 1=已上链
     */
    public chainStatus: number;
    /**
     * 0=默认 1=未中奖 2=已中奖
     */
    public prizeStatus: number;
    /**
     * 0=未过期 1=已过期
     */
    public lateStatus: number;
    /**
     * 过期时间
     */
    public expTime: number;

    public get m_iLevel(): number {
        return this._m_iLevel > 0 ? this._m_iLevel : 1;
    }
    public set m_iLevel(value: number) {
        this._m_iLevel = value ? value : 0;
    }

    public get m_iPk(): string {
        return this._m_iPk;
    }

    public set m_iPk(value: string) {
        this._m_iPk = value;
    }
    public copyItem(): ItemVo {
        let vo: ItemVo = new ItemVo();
        vo.id = this.id;
        vo.m_iOriginalId = this.m_iOriginalId;
        return vo;
    }
    public get m_bTry(): boolean {
        if (this.id == this.m_iOriginalId) {
            this._m_bSet = false;
        } else {
            this._m_bSet = true;
        }
        return this._m_bSet;
    }

    private _itemName: string;

    public set itemName(value: string) {
        this._itemName = value;
    }
    public get itemName(): string {
        if (this._itemName) return this._itemName;
        return GameLanguageMgr.getLanguage(this.itemItem.name);
    }
    public set m_bTry(value: boolean) {
        this._m_bSet = value;
    }
    public m_bSalon: boolean = false;
    public get id(): number {
        return this._m_iId;
    }
    private m_bIsSetId: boolean = false;
    public set id(value: number) {
        this._m_iId = value;
        if (!this.m_bIsSetId) {
            this.m_bIsSetId = true;
            this.m_iOriginalId = value;
        }
        this.setConfigData();
    }

    private setConfigData(): void {
        if (this.id == 0) {
            return;
        }
        if (this.type == EnumItemType.TYPE_TOKEN) {
            //游戏外货币
            this.quality = 1;
            let tokenData = AssetManager.getTokenDataBySyId(this.id);
            if (tokenData) {
                this.itemName = tokenData.symbol;
                this.iconURL = GameResourceManager.getCurrencyIcon(tokenData.symbol);
            } else {
                this.iconURL = "";
                this.itemName = "";
            }
            return;
        }
        this.itemItem = SheetDataManager.m_dicItems.get(this.id.toString());
        if (!this.itemItem) {
            console.log("[          <items> find out id:" + this.id + "             ]");
            return;
        }
        this.subType = parseInt(this.itemItem.subType + "");
        this.backType = parseInt(this.itemItem.backPack + "");

        this.type = parseInt(this.itemItem.type + "");

        if (this.itemItem.buy_price) {
            this.m_iPrice = this.itemItem.buy_price[0][1];
            let montyId: number = this.itemItem.buy_price[0][0];
            let monyItem: ItemItem = SheetDataManager.m_dicItems.get(montyId);
            if (monyItem) {
                this.m_strBuyIcon = GameResourceManager.getItemIcon(monyItem.icon);
            }
        }
        if (this.itemItem.sell_price) {
            this.m_iSellPrice = parseFloat(this.itemItem.sell_price[0][1]);
            // montyId = this.m_itemVo.sell_price[0][0];
            // monyItem = SheetDataManager.m_dicItems.get(montyId);
            // if(monyItem ) {
            //     this.m_strSellIcon = GameResourceManager.getIconUrl(monyItem.item_img);
            // }
        }
        this.quality = this.itemItem.quality;
        this.setQualityData();
    }

    public m_arrQualityData: any[];
    private setQualityData(): void {
        this.m_arrQualityData = this.itemItem.starArr;
        return;
    }

    private _iconURL: string;
    public set iconURL(value: string) {
        this._iconURL = value;
    }
    public get iconURL(): string {
        if (this.type == EnumItemType.TYPE_TOKEN) {
            //游戏外货币
            return this._iconURL;
        }
        return GameResourceManager.getItemIcon(this.itemItem.icon);
    }
    public copy(): ItemVo {
        let itemVo: ItemVo = new ItemVo(this.id);
        itemVo.m_iLevel = this.m_iLevel;
        return itemVo;
    }

    public compareName(): string {
        return GameLanguageMgr.getLanguage(this.itemItem.name);
    }
    public compareQuality(): number {
        return parseFloat(this.quality + "");
    }
    public compareSellPrice(): number {
        return parseFloat(this.itemItem.sell_price[1] + "");
    }
    public compareNum(): number {
        return parseFloat(this.num + "");
    }
    public compareLevel(): number {
        return parseFloat(this.m_iLevel + "");
    }
    public compareTypeId(): number {
        return parseInt(this.id + "");
    }
}
