    async onRegister() {
        // E 12 z 6
        // let createName: string = this.input_name.text;
        let walletAddress = EthereumManager.walletAddress || "";
        let last5Chars = walletAddress.length >= 5 ? walletAddress.slice(-5) : walletAddress;
        let createName: string = "User-" + last5Chars;

        let sex: number = 1;
        createName = createName.trim();
        if (createName == "") {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(25));
            return;
        }
        // 检查非法字符
        // const invalidChars = /[,\\<>{}[\]~!@#$%^&*()+=|;:'"`]/;
        // const invalidChars = /[,，\\<>{}[\]~!@#$%^&*()+=|;:'"`]/;
        // if (invalidChars.test(createName)) {
        //     NoticeMgr.notice(GameLanguageMgr.getLanguage(610102)); //"昵称包含非法字符：, \\ < > { } [ ] ~ ! @ # $ % ^ & * ( ) + = | ; : ' " `
        //     return;
        // }
        if (GlobalDataManager.countryId == -1) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(33)); //"请选择国家"
            return;
        }
        const currentUrl = new URL(window.location.href);
        // 解析 URL 参数
        const params = new URLSearchParams(currentUrl.search);
        // 获取 referral 参数
        let referral = params.get("referral");

        // 如果没有找到referral参数，尝试从hash中获取
        if (!referral) {
            const hashParams = new URLSearchParams(currentUrl.hash.substring(1));
            referral = hashParams.get("referral");
        }

        // 如果还是没有找到，尝试手动解析URL
        if (!referral) {
            const url = window.location.href;
            const referralMatch = url.match(/referral=([^&]+)/);
            if (referralMatch && referralMatch[1]) {
                referral = referralMatch[1];
            }
        }
        // this.box_country.visible = true;

        console.log("referral: ", referral);
        await EthereumManager.createAcccount(createName, sex, GlobalDataManager.headId.toString(), GlobalDataManager.countryId, referral);
    }

