    /**
     * 请求玩家详细信息
     */
    private requestInvitePlayerInfo(roleId: string): void {
        const cmdId = com.snake.socket.MessageType.MSG_REQUEST_INFO;
        const requestData = com.snake.socket.CS_REQUEST_INFO.fromObject({ roleId: roleId, type: 2 });
        HallWebSocket.send(cmdId, requestData);
    }

    initReferral() {
        // 获取当前的 URL
        const currentUrl = new URL(window.location.href);
        // 解析 URL 参数
        const params = new URLSearchParams(currentUrl.search);
        // 获取 referral 参数
        const referral = params.get("referral");
        let hasReferral = false;

        if (referral) {
            this.requestInvitePlayerInfo(referral);
            hasReferral = true;
        } else {
            // 如果没有找到referral参数，尝试从hash中获取
            const hashParams = new URLSearchParams(currentUrl.hash.substring(1));
            const hashReferral = hashParams.get("referral");
            if (hashReferral) {
                this.requestInvitePlayerInfo(hashReferral);
                hasReferral = true;
            } else {
                // 如果还是没有找到，尝试手动解析URL
                const url = window.location.href;
                const referralMatch = url.match(/referral=([^&]+)/);
                if (referralMatch && referralMatch[1]) {
                    this.requestInvitePlayerInfo(referralMatch[1]);
                    hasReferral = true;
                } else {
                    this.box_code.visible = false;
                    hasReferral = false;
                }
            }
        }

        // 根据是否有邀请人信息调整box_country的y坐标
        this.box_country.y = hasReferral ? 333 : 413;
        this.box_country.visible = true;
    }

