const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import { MemberClubListItemBase } from "./MemberClubListItem.generated";

@regClass('3U7la1usRgKQbfApkNfiHQ==')
export class MemberClubListItem extends MemberClubListItemBase {
    public constructor() {
        super();
    }

    private referralData: any;

    public createChildren(): void {
        super.createChildren();
    }

    onEnable(): void {}

    onDisable(): void {}

    public set dataSource(value: any) {
        if (!value) return;

        super.dataSource = value;
        this.referralData = value;
        console.log("MemberClubListItem", value);
        // ['1010,10001,tongtong33,1,3']
        let data = value.split(",");
        this.tf_name.text = data[3];
        this.PlayerIcon.setHeadSkinAndRoldId(data[2], data[0]);
        this.tf_memberLevel.text = data[4];
        // this.tf_match.text = data[5];
        this.img_flag.skin = GameResourceManager.getCountryIconById(data[1]);
        const index = (this.parent?.parent as Laya.List)?.array?.indexOf(value) ?? 0;
        // 奇数行显示背景，偶数行不显示
        this.img_bg.visible = index % 2 === 1;
        // 初始显示倒计时
    }
}
