const { regClass } = Laya;
import GameLanguageMgr from "../../common/GameLanguageMgr";
import GameResourceManager from "../../common/GameResourceManager";
import { ComUtil } from "../../utils/ComUtil";
import NoticeMgr from "../notice/NoticeMgr";
import { RankListItemBase } from "./RankListItem.generated";

@regClass('ILpWxZ9qRRiahqxWqEMA9g==')
export class RankListItem extends RankListItemBase {
    public propItem: any;
    private address: string; //按钮防止连点锁

    public constructor() {
        super();
    }
    onEnable(): void {
        this.btn_copy.on(Laya.Event.CLICK, this, this.copyAddress);
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        if (!value) {
            this.visible = false;
            return;
        }
        this.tf_address.text = ComUtil.shortenString(value.addr, 6, 4);
        this.PlayerIcon.dataSource = value;
        this.tf_name.text = ComUtil.fitTextToLabel(value.userName, this.tf_name);
        this.tf_num.text = value.num;
        this.address = value.addr;

        // 获取当前项在列表中的索引位置，用于控制背景显示
        const index = (this.parent?.parent as Laya.List)?.array?.indexOf(value) ?? 0;

        // 奇数行显示背景，偶数行不显示
        this.img_bg.visible = index % 2 === 1;

        this.tf_rank.text = `${index + 1}`;

        this.img_flag.skin = GameResourceManager.getCountryIconById(value.country);

        //前三名显示img_title；
        //前三名的背景显示img_b1,img_b2,img_b3
        if (index < 3) {
            this.img_title.visible = true;
            this.tf_rank.visible = false;
            this.img_title.skin = `res/rank/img_b${index + 1}.png`;
        } else {
            this.img_title.visible = false;
            this.tf_rank.visible = true;
        }

        // img_title
    }

    private copyAddress(): void {
        if (this.address) {
            doCopy(this.address);
            NoticeMgr.notice(GameLanguageMgr.getLanguage(19)); //复制成功
        }
    }
}
