const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { SceneType } from "../../common/baseScene/SceneType";
import { ShopItem } from "../../data/sheetItem/shop/ShopItem";
import { SnakeItem } from "../../data/sheetItem/snake/SnakeItem";
import Signal from "../../global/event/Signal";
import { AnimationUtil } from "../../utils/AnimationUtil";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { ShopSceneBase } from "./ShopScene.generated";
import NoticeMgr from "../notice/NoticeMgr";
import SheetDataManager from "../../global/SheetDataManager";
import AssetManager from "../../manager/AssetManager";
import { GameEvent } from "../../global/event/GameEvent";
import { TokenData } from "../../data/dto/TokenData";
import SceneManager from "../../common/SceneManager";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import GameResourceManager from "../../common/GameResourceManager";
import GlobalDataManager from "../../global/GlobalDataManager";
import KnapsackManager from "../../global/KnapsackManager";
import { NumberUtil } from "../../utils/NumberUtil";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import SoundMgr from "../../common/SoundMgr";

@regClass('IPCUkD5kRse3Gz5tw0Aovw==')
export class ShopScene extends ShopSceneBase {
    public m_iLayerType: number;
    public m_iPositionType: number;
    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;
    }
    private currTab: number = 0;
    private type: number = 1;
    private selectItemId: number = -1;
    private shopId: number = 1; //选中的蛇的id
    private isButtonLocked: boolean = false; // 添加按钮锁定状态变量
    private buttonLockTime: number = 2000; // 按钮锁定时间为1.5秒

    onOpened(datas: any): void {
        //根据参数切换优先显示的类目
        if (datas && datas.length > 0) {
            this.type = datas[0];
            if (datas[1] != undefined) {
                this.selectItemId = datas[1];
            }
            this.onClickTab(this.type);
            this.onTabClick(1);
        } else {
            //没有指定就显示默认第一个
            this.selectItemId = 1;
            this.onTabClick(this.selectItemId);
        }
    }

    onEnable(): void {
        AssetManager.requestCoinInfo();
        AnimationUtil.startJellyScaleAnimation(this.tf_tittle)
        this.tf_diamon.text =  `${parseFloat(GlobalDataManager.playerDto.score.toFixed(4)).toString()}`;
        //注册事件顶部按钮点击（切换蛇）
        for (let i = 0; i < 4; i++) {
            (this as any)["tab" + i].on(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }

        //注册事件左侧按钮点击（切换类型）
        for (let i = 1; i < 3; i++) {
            (this as any)["btn_" + i].on(Laya.Event.CLICK, this, this.onClickTab, [i]);
        }

        this.initShopList();
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_SHOP_BUY, this, this.onBuySuccess);
        this.btn_back.on(Laya.Event.CLICK, this, this.setToMainScene);
        this.btn_left.on(Laya.Event.CLICK, this, this.clickLeftAndRight, [true]);
        this.btn_right.on(Laya.Event.CLICK, this, this.clickLeftAndRight, [false]);
        this.btn_buy.on(Laya.Event.CLICK, this, this.onRecruit);
        Signal.on(GameEvent.UPDATE_TOKEN_BALANCE, this, this.onTokenBalanceUpdate);
    }

    /**
     * 设置Tab的选中状态
     * @param value
     */
    public setTab(value: number) {
        for (let i = 1; i < 3; i++) {
            if (value == i) {
                (this as any)["btn_" + i].getChildByName("selectBox1").visible = true;
                (this as any)["btn_" + i].getChildByName("selectBox2").visible = false;
            } else {
                (this as any)["btn_" + i].getChildByName("selectBox1").visible = false;
                (this as any)["btn_" + i].getChildByName("selectBox2").visible = true;
            }
        }
    }

    /**
     * 左侧切换商品类型的点击事件
     * @param _index
     * @returns
     */
    async onClickTab(_index: number) {
        if (this.currTab == _index) return;
        this.type = _index;
        this.setTab(_index);
        if (_index == 1) {
            //nft
            this.box_middle.visible = true;
            this.tabBox.visible = true;
            this.box_shop.visible = false;
            this.tf_nft2.stroke = 5;
            this.tf_nft2.fontSize = 32;
            this.tf_props2.stroke = 0;
            this.tf_props2.fontSize = 25;
        } else if (_index == 2) {
            //道具
            this.box_middle.visible = false;
            this.tabBox.visible = false;
            this.box_shop.visible = true;
            this.tf_nft2.stroke = 0;
            this.tf_nft2.fontSize = 25;
            this.tf_props2.stroke = 5;
            this.tf_props2.fontSize = 32;
        }
    }

    private setToMainScene(): void {
        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
    }

    public removeEvent(): void {
        for (let i = 0; i < 4; i++) {
            (this as any)["tab" + i].off(Laya.Event.CLICK, this, this.onTabClick, [i]);
        }

        for (let i = 1; i < 3; i++) {
            (this as any)["btn_" + i].off(Laya.Event.CLICK, this, this.onClickTab, [i]);
        }

        this.btn_back.off(Laya.Event.CLICK, this, this.setToMainScene);
        this.btn_left.off(Laya.Event.CLICK, this, this.clickLeftAndRight, [true]);
        this.btn_right.off(Laya.Event.CLICK, this, this.clickLeftAndRight, [false]);
        this.btn_buy.off(Laya.Event.CLICK, this, this.onRecruit);

        // 注销Signal事件
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_SHOP_BUY, this, this.onBuySuccess);
        Signal.off(GameEvent.UPDATE_TOKEN_BALANCE, this, this.onTokenBalanceUpdate);
    }

    /**
     * 添加清除所有定时器的方法
     */
    private clearAllTimer(): void {
        // 清除所有定时器
        Laya.timer.clearAll(this);
        // 重置按钮锁定状态
        this.isButtonLocked = false;
    }

    /**
     * Tab点击事件处理
     * @param index 被点击的Tab索引
     */
    private onTabClick(index: number) {
        // Tab相关常量定义
        const TAB_COUNT = 4;
        const SKIN_SELECTED_FIRST = "res/shop/img_Button_1.png";
        const SKIN_SELECTED_OTHER = "res/shop/img_btlv.png";
        const SKIN_UNSELECTED_FIRST = "res/shop/img_bt1_2.png";
        const SKIN_UNSELECTED_OTHER = "res/shop/img_Button_4.png";
        const STROKE_COLOR = "#0785f5";
        const STROKE_WIDTH = 5;
        if (this.snake_sk) {
            this.snake_sk.visible = false;
        }
        // 清除所有定时器和重置状态
        this.clearAllTimer();

        // 遍历所有Tab按钮
        for (let i = 0; i < TAB_COUNT; i++) {
            // 获取当前Tab按钮和其标题文本组件
            const tab = (this as any)[`tab${i}`];
            const title = tab.getChildByName("tf_tit");

            // 判断当前Tab是否被选中，是否是第一个Tab
            const isSelected = index === i;
            const isFirstTab = i === 0;
            this.selectItemId = index;
            // 根据Tab位置和选中状态设置不同的皮肤
            tab.skin = isFirstTab
                ? isSelected
                    ? SKIN_SELECTED_FIRST
                    : SKIN_UNSELECTED_FIRST
                : isSelected
                    ? SKIN_SELECTED_OTHER
                    : SKIN_UNSELECTED_OTHER;

            // 设置文字描边效果：选中时显示描边，未选中时隐藏描边
            title.stroke = isSelected ? STROKE_WIDTH : 0;
            title.strokeColor = STROKE_COLOR;

            let shopId = 1001;
            let snakeId = 101;
            //根据index来设置不同的蛇的显示（有些蛇不显示价格）
            // if (this.egg_sk) {
            //     this.egg_sk.paused();
            // }
            switch (index) {
                case 0:
                    shopId = null;
                    snakeId = 101;
                    if (isSelected) {
                        this.snake_sk.source = ""
                        let snakeAniJson = GameResourceManager.getSnakeAni(snakeId);
                        this.snake_sk.source = snakeAniJson;
                        this.snake_sk.visible = true;
                        if (this.snake_sk && this.snake_sk.templet) {
                            this.snake_sk.play("animation", true)
                        }
                        this.eggBox.visible = false;
                        // this.img_snake.visible = true;
                    }
                    break;
                case 1:
                    shopId = 1001;
                    snakeId = 102;
                    if (isSelected) {
                        this.img_egg.visible = false
                        this.egg_sk.visible = true;
                        if (this.egg_sk && this.egg_sk.templet) {
                            this.egg_sk.play("animation1", true);
                        }
                        this.eggBox.visible = true;
                        // this.img_snake.visible = false;
                    }
                    break;
                case 2:
                    shopId = 1002;
                    snakeId = 103;
                    if (isSelected) {
                        this.img_egg.visible = true
                        this.egg_sk.visible = false;
                        this.img_egg.skin = "res/shop/img_dan_2.png";
                        this.eggBox.visible = true;
                        // this.img_snake.visible = false;
                    }
                    break;
                case 3:
                    snakeId = null;
                    shopId = null;
                    snakeId = 104;
                    if (isSelected) {
                        this.img_egg.visible = true
                        this.egg_sk.visible = false;
                        this.img_egg.skin = "res/shop/img_dan_3.png";
                        this.img_egg.visible = true;
                        // this.img_snake.visible = false;
                    }
                    break;
                default:
                    break;
            }
            this.shopId = shopId;
            if (snakeId && isSelected) {
                //显示蛇的属性
                var snakeItem: SnakeItem = SheetDataManager.m_dicSnakes.get(snakeId);
                let initLength = this.attribute_1.getChildByName("tf_value");// 初始速度
                let maxLength = this.attribute_2.getChildByName("tf_value");// 最大长度
                let suctionRadius = this.attribute_3.getChildByName("tf_value");//吸食半径
                let speed = this.attribute_4.getChildByName("tf_value");
                let accelerationFactor = this.attribute_5.getChildByName("tf_value");
                if (snakeItem) {
                    // return
                    if(snakeId >= 103){
                        (initLength as Laya.Label).text = "?";
                        (maxLength as Laya.Label).text = "?";
                        (suctionRadius as Laya.Label).text = "?";
                        (speed as Laya.Label).text = "?";
                        (accelerationFactor as Laya.Label).text = "?";
                    }else{
                        (initLength as Laya.Label).text = `${snakeItem.initLength}`;
                        (maxLength as Laya.Label).text = `${snakeItem.maxLength}`;
                        // (initLength as Laya.Label).text = `${snakeItem.initLength/snakeItem.intervalBoneToDrawSkin}`;
                        // (maxLength as Laya.Label).text = `${snakeItem.maxLength/snakeItem.intervalBoneToDrawSkin}`;
                        (suctionRadius as Laya.Label).text = `${snakeItem.suctionRadius}`;
                        (speed as Laya.Label).text = `${snakeItem.baseSpeed}`;
                        (accelerationFactor as Laya.Label).text = `${snakeItem.accelerationFactor}`;
                    }

                }
            }
            if (shopId) {
                //显示配表中道具的属性
                let shopItem: ShopItem = SheetDataManager.m_dicShops.get(shopId);
                if (shopItem) {
                    this.tf_price.text = `${shopItem.cost} USDT`;
                    this.btn_buy.visible = true;
                } else {
                    this.btn_buy.visible = false;
                }
            } else {
                this.btn_buy.visible = false;
            }

            //根据index来显示左右切换按钮的状态
            if (this.selectItemId <= 0) {
                this.btn_left.disabled = true;
            } else {
                this.btn_left.disabled = false;
            }
            if (this.selectItemId >= 3) {
                this.btn_right.disabled = true;
            } else {
                this.btn_right.disabled = false;
            }
        }
    }

    /**
     * 左右切换按钮点击事件
     * @param isLeft
     */
    private clickLeftAndRight(isLeft: boolean) {
        if (isLeft && this.selectItemId > 0) {
            this.selectItemId--;
            this.onTabClick(this.selectItemId);
        }
        if (!isLeft && this.selectItemId < 3) {
            this.selectItemId++;
            this.onTabClick(this.selectItemId);
        }
    }

    /**
     * 初始化商店列表
     */
    private initShopList(): void {
        let shopData = [];
        let shopItemData = SheetDataManager.m_dicShops;
        if (shopItemData && shopItemData.values) {
            //把shopItemData.values里面所有type为2的筛选出来
            shopData = Array.from(shopItemData.values).filter((item) => item.type === 2);
            this.shopList.array = shopData;
        }

        let data = KnapsackManager.getKnapsackItemById(10001);
        if(data){
            this.tf_diamon.text = `${parseFloat(data.num.toFixed(4)).toString()}`;
        }else{
            this.tf_diamon.text = "0"
        }
    }

    private onBuySuccess(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_SHOP_BUY = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_SHOP_BUY);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // 购买成功回调
            if (msgBody && msgBody.items) {
                // 更新商城数据
                // 显示购买成功提示
                // NoticeMgr.notice("Purchase successful!");
                console.log("buySNake============>", msgBody);
                // 播放购买成功音效
                SoundMgr.playSoundByName(SoundMgr.soundName_snakeBuy);

                if(msgBody.snake && msgBody.snake.skin){
                    // let skinId = msgBody.snake.skin - 100;
                    if (this.egg_sk && this.egg_sk.templet) {
                        this.egg_sk.play("animation2", false);
                    }
                    this.snake_sk.source = ""
                    this.btn_buy.visible = false;
                    let snakeAniJson = GameResourceManager.getSnakeAni(msgBody.snake.skin);
                    this.snake_sk.source = snakeAniJson
                    Laya.timer.once(500, this, () => {
                        this.snake_sk.visible = true;
                        if (this.snake_sk && this.snake_sk.templet) {
                            this.snake_sk.play("animation", true)
                        }
                    })
    
                    // 7秒后播放动画1
                    Laya.timer.once(7000, this, () => {
                        if (this.selectItemId == 1) {
                            if (this.snake_sk) {
                                this.snake_sk.visible = false;
                            }
                            if (this.egg_sk && this.egg_sk.templet) {
                                this.egg_sk.play("animation1", true);
                            }
                            this.btn_buy.visible = true;
                        }
                    })
                    AssetManager.requestCoinInfo();
                }

            }
        } else {
            // 购买失败提示
            if (msgcode == com.snake.socket.MessageCode.NOT_ENOUGH_TOKEN) {
                NoticeMgr.notice(GameLanguageMgr.getLanguage(72));
            }else {
                NoticeMgr.notice(GameLanguageMgr.getLanguage(73));
            }
        }
    }

    /**
     * 商城购买
     */
    private onRecruit(): void {
        // 检查按钮是否锁定，如果锁定则直接返回
        if (this.isButtonLocked) {
            return;
        }

        // 锁定按钮，1.5秒后解锁
        this.isButtonLocked = true;
        Laya.timer.once(this.buttonLockTime, this, () => {
            this.isButtonLocked = false;
        });


        const cmdId = com.snake.socket.MessageType.MSG_SHOP_BUY;
        var snakeItem: SnakeItem = SheetDataManager.m_dicSnakes.get(this.shopId);
        console.log(snakeItem);
        if (this.shopId) {
            const requestData = com.snake.socket.CS_SHOP_BUY.fromObject({
                id: this.shopId,
                symbolId: 10,
                num: 1
            });
            HallWebSocket.send(cmdId, requestData);
        }
    }

    /**
     * 处理代币余额更新事件
     * @param tokenData 资产数据数组
     */
    private onTokenBalanceUpdate(tokenData: TokenData[]): void {
        this.showAssetData(tokenData);
    }

    /**
     * 显示资产数据
     * @param tokenData 资产数据数组
     */
    private showAssetData(tokenData: TokenData[]) {
        //查找symbolId为10的资产数据    
        const targetToken = tokenData.find((token) => token.symbolId === 10);
        const balance = targetToken ? targetToken.balance : 0;
        this.tf_usdt.text = NumberUtil.filterNumFormat(balance, 2, true);
    }

    onDisable(): void {
        this.removeEvent();
        // 重置按钮锁定状态
        this.isButtonLocked = false;
    }
}
