import { SceneType } from "../../common/baseScene/SceneType";
import SceneManager from "../../common/SceneManager";
import MatchDto from "../../data/dto/MatchDto";
import { EnumMatch } from "../../data/enumData/EnumMatch";
import FoodManager from "../../game/food/FoodManager";
import FrameAiManager from "../../game/ai/FrameAiManager";
import SnakeManager from "../../game/snake/SnakeManager";
import Constants from "../../global/config/Constants";
import MatchModel from "../match/MatchModel";
import { RoomDto } from "../../data/dto/RoomDto";
import Signal from "../../global/event/Signal";
import HallWebSocket from "../../network/HallWebSocket";
import { com } from "../../network/pb/socket";
import { SocketDataUtil } from "../../utils/SocketDataUtil";
import AiSnakeManager from "../../game/snake/AiSnakeManager";
import { ModuleManager } from "../../common/ModuleManager";
import { ModuleName } from "../../global/ModuleName";
import NodeManager from "../../global/NodeManager";
import { Quick } from "../../utils/Quick";
import RoomWebSocket from "../../network/RoomWebSocket";
import NoticeMgr from "../notice/NoticeMgr";
import GameLanguageMgr from "../../common/GameLanguageMgr";

class EnterRoomManager {
    private static _instance: EnterRoomManager;

    public static getInstance(): EnterRoomManager {
        if (EnterRoomManager._instance == null) {
            EnterRoomManager._instance = new EnterRoomManager();
            return EnterRoomManager._instance;
        } else {
            return EnterRoomManager._instance;
        }
    }

    raceId: string = null;

    constructor() {
        this.init();
    }

    public init(): void {
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_REQUEST_ROOM_ADDR, this, this.onRequestRoomAddr);
    }
    /**
     * 返回房间信息
     * @param msgBase
     * @param msgcode
     */
    public onRequestRoomAddr(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_REQUEST_ROOM_ADDR = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_REQUEST_ROOM_ADDR);
        if (msgcode == com.snake.socket.MessageCode.SYS_NORMAL) {
            // var addr = msgBody.addr;
            // console.log("onRequestRoomAddr: " + addr);
            // if (addr) {
            //     var lastIndex = addr.lastIndexOf("#");
            //     if (lastIndex != -1) {
            //         addr = addr.slice(0, lastIndex);
            //     }
            // }

            var roomDto: RoomDto = MatchModel.roomDto;
            if (!roomDto) {
                roomDto = new RoomDto();
            }
            // roomDto.connectAddr = addr;
            MatchModel.roomDto = roomDto;
            ModuleManager.intance.closeAll();
            SceneManager.isCloseAll = false;
            ModuleManager.intance.openModule(ModuleName.MatchReadyView); //增加过渡页

            SceneManager.setCurrentScene(SceneType.M_SCENE_SNAKE_MATCH);
        } else {
            MatchModel.roomDto = null;
            if (msgcode == com.snake.socket.MessageCode.NOT_ENOUGH_TOKEN) {
                Quick.moneyNotEnought();
                // NoticeMgr.notice(GameLanguageMgr.getLanguage(72));
            }
        }
    }

    /**
     * 请求pvp房间
     */
    goPvpArenaScene(roomItemId: number, ticketType: number, ticketAmount: number, roomIndex: number, tokenIndex: number, symbol: string) {
        this.closePvpMatchScene();
        EnumMatch.matchType = EnumMatch.MATCH_TYPE_PVP;
        EnumMatch.arenaType = EnumMatch.ARENA_TYPE_PVP;
        var roomDto: RoomDto = new RoomDto();
        roomDto.pvpRoomIndex = roomIndex;
        roomDto.pvpTokenIndex = tokenIndex;
        roomDto.symbol = symbol;
        console.log(
            "goPvpArenaScene",
            "roomType: " + roomItemId,
            "ticketType: " + ticketType,
            "ticketAmount: " + ticketAmount,
            "roomIndex: " + roomIndex,
            "tokenIndex: " + tokenIndex,
            "symbol: " + symbol
        );

        MatchModel.roomDto = roomDto;

        //房间类型1无尽模式（后续有其他房间类型再添加）
        var cmdId = com.snake.socket.MessageType.MSG_REQUEST_ROOM_ADDR;
        // var o = com.snake.socket.CS_REQUEST_ROOM_ADDR.fromObject({ type: 1, ticketId: 10 });
        let point = NodeManager.getNodePoint();
        var o = com.snake.socket.CS_REQUEST_ROOM_ADDR.fromObject({
            ticketId: ticketType,
            ticketValue: ticketAmount,
            roomType: roomItemId,
            point: point
        });

        HallWebSocket.send(cmdId, o);
    }

    /**
     * 请求pvp房间
     */
    watchPvpArenaScene(roomItemId: number, roomNo: string) {
        console.log("watchPvpArenaScene", "roomType: " + roomItemId, "roomNo: " + roomNo);
        this.closePvpMatchScene();
        EnumMatch.matchType = EnumMatch.MATCH_TYPE_PVP;
        EnumMatch.arenaType = EnumMatch.ARENA_TYPE_PVP;
        var roomDto: RoomDto = new RoomDto();
        roomDto.roomNo = roomNo;
        var isWatch = true;
        // roomDto.pvpTokenIndex = tokenIndex;
        roomDto.isWatch = isWatch;
        roomDto.connectAddr = NodeManager.getWsUrlByRoomNo(roomNo);
        if (!roomDto.connectAddr) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(2004));
            return;
        }
        MatchModel.roomDto = roomDto;
        // ModuleManager.intance.closeAll();
        // SceneManager.isCloseAll = false;
        // ModuleManager.intance.openModule(ModuleName.MatchReadyView); //增加过渡页

        // SceneManager.setCurrentScene(SceneType.M_SCENE_SNAKE_MATCH, isWatch);

        RoomWebSocket.initSocket();
    }

    /**
     * 请求俱乐部房间
     */
    goCLubArenaScene(roomItemId: number, ticketType: number, ticketAmount: number, roomNo: string, symbol: string) {
        this.closePvpMatchScene();
        EnumMatch.matchType = EnumMatch.MATCH_TYPE_PVP;
        EnumMatch.arenaType = EnumMatch.ARENA_TYPE_JULEBU;
        //房间类型1无尽模式（后续有其他房间类型再添加）
        var cmdId = com.snake.socket.MessageType.MSG_REQUEST_ROOM_ADDR;
        // var o = com.snake.socket.CS_REQUEST_ROOM_ADDR.fromObject({ type: 1, ticketId: 10 });
        let point = NodeManager.getPointByRoomNo(roomNo);

        var roomDto: RoomDto = new RoomDto();
        roomDto.roomNo = roomNo;
        roomDto.symbol = symbol;
        var isWatch = false;
        // roomDto.pvpTokenIndex = tokenIndex;
        roomDto.isWatch = isWatch;
        roomDto.connectAddr = NodeManager.getWsUrlByRoomNo(roomNo);
        if (!roomDto.connectAddr) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(2004));
            return;
        }
        MatchModel.roomDto = roomDto;

        var o = com.snake.socket.CS_REQUEST_ROOM_ADDR.fromObject({
            ticketId: ticketType,
            ticketValue: ticketAmount,
            roomType: roomItemId,
            point: point,
            roomNo: roomNo
        });

        HallWebSocket.send(cmdId, o);
    }
    /**
     * 请求比赛模式房间
     */
    goMatchArenaScene(roomItemId: number, ticketType: number, ticketAmount: number, roomNo: string, symbol: string, raceId: string = null) {
        this.closePvpMatchScene();
        EnumMatch.matchType = EnumMatch.MATCH_TYPE_PVP;
        EnumMatch.arenaType = EnumMatch.ARENA_TYPE_MATCH;
        //房间类型1无尽模式（后续有其他房间类型再添加）
        var cmdId = com.snake.socket.MessageType.MSG_REQUEST_ROOM_ADDR;
        // var o = com.snake.socket.CS_REQUEST_ROOM_ADDR.fromObject({ type: 1, ticketId: 10 });
        let point = NodeManager.getPointByRoomNo(roomNo);

        var roomDto: RoomDto = new RoomDto();
        roomDto.roomNo = roomNo;
        roomDto.symbol = symbol;
        var isWatch = false;
        // roomDto.pvpTokenIndex = tokenIndex;
        roomDto.isWatch = isWatch;
        roomDto.connectAddr = NodeManager.getWsUrlByRoomNo(roomNo);
        if (!roomDto.connectAddr) {
            NoticeMgr.notice(GameLanguageMgr.getLanguage(2004));
            return;
        }
        MatchModel.roomDto = roomDto;

        var o = com.snake.socket.CS_REQUEST_ROOM_ADDR.fromObject({
            // ticketId: ticketType,
            // ticketValue: ticketAmount,
            roomType: roomItemId,
            point: point,
            roomNo: roomNo,
            raceId: raceId
        });

        HallWebSocket.send(cmdId, o);
    }

    /**
     * 请求pve房间
     */
    async goAiArenaScene() {
        // ModuleManager.intance.openModule(ModuleName.AiArenaStartDialog); //增加过渡页

        FrameAiManager.sendAiEnter();
    }
    /**
     * 请求pve房间
     */
    async goAiArenaSceneBack() {
        this.closePveMatchScene();
        ModuleManager.intance.closeAll();
        SceneManager.isCloseAll = false;
        ModuleManager.intance.openModule(ModuleName.MatchReadyView); //增加过渡页
        EnumMatch.matchType = EnumMatch.MATCH_TYPE_PVE;
        EnumMatch.arenaType = EnumMatch.ARENA_TYPE_PVE;
        // return;
        var matchDto = new MatchDto();
        matchDto.members = [];

        var myPlayer = (SnakeManager.getInstance() as AiSnakeManager).spawnRandomPlayerObject("", true, true);
        // console.log("goAiArenaScene myPlayer: ", myPlayer);
        // myPlayer.skin=109;

        matchDto.members.push(myPlayer);

        matchDto.myPlayerObject = myPlayer;

        var aiSnakes = await (SnakeManager.getInstance() as AiSnakeManager).spawnSnakes();
        matchDto.members = matchDto.members.concat(aiSnakes);

        matchDto.item = FoodManager.spawnFoods();

        matchDto.matchType = EnumMatch.MATCH_TYPE_PVE;
        matchDto.remainderCd = Constants.snake.battleCd;
        MatchModel.matchDto = matchDto as MatchDto;
        // FrameAiManager.sendAiEnter();
        SceneManager.setCurrentScene(SceneType.M_SCENE_AI_ARENA);
    }

    private closePvpMatchScene() {
        if (SceneManager.currSceneName == SceneType.M_SCENE_SNAKE_MATCH) {
            SceneManager.m_sceneCurrent.close();
            SceneManager.m_sceneCurrent = null;
        }
    }
    private closePveMatchScene() {
        if (SceneManager.currSceneName == SceneType.M_SCENE_AI_ARENA) {
            SceneManager.m_sceneCurrent.close();
            SceneManager.m_sceneCurrent = null;
        }
    }
}
export default EnterRoomManager.getInstance();
