import GameLanguageMgr from "../../../common/GameLanguageMgr";
import SheetDataManager from "../../../global/SheetDataManager";
import { SnakeItem } from "../../sheetItem/snake/SnakeItem";

export class SnakeVo {
    public constructor(__id: number = 0) {
        if (__id == 0) {
            return;
        }
        this.id = __id;
    }
    public m_iOriginalId: number;
    private _m_iId: number;

    unkey: number;
    private _m_iLevel: number = 0;

    public snakeItem: SnakeItem;

    public attr: string[]; //升级属性
    public skin: number; //皮肤
    public upgrade: boolean; //是否可升级
    public type: number; //稀有度

    public isShopEntry: boolean = false;

    public get m_iLevel(): number {
        return this._m_iLevel > 0 ? this._m_iLevel : 1;
    }
    public set m_iLevel(value: number) {
        this._m_iLevel = value ? value : 0;
    }

    private _snakeName: string;

    public set snakeName(value: string) {
        this._snakeName = value;
    }
    public get snakeName(): string {
        if (this._snakeName) return this._snakeName;
        return GameLanguageMgr.getLanguage(this.snakeItem.name);
    }
    public get id(): number {
        return this._m_iId;
    }
    private m_bIsSetId: boolean = false;
    public set id(value: number) {
        this._m_iId = value;
        if (!this.m_bIsSetId) {
            this.m_bIsSetId = true;
            this.m_iOriginalId = value;
        }
        this.setConfigData();
    }

    private setConfigData(): void {
        if (this.id == 0) {
            return;
        }

        this.snakeItem = SheetDataManager.m_dicSnakes.get(this.id.toString());
        if (!this.snakeItem) {
            console.log("[          <snakes> find out id:" + this.id + "             ]");
            return;
        }
    }
    public copy(): SnakeVo {
        let snakeVo: SnakeVo = new SnakeVo(this.id);
        snakeVo.m_iLevel = this.m_iLevel;
        return snakeVo;
    }

    public compareName(): string {
        return GameLanguageMgr.getLanguage(this.snakeItem.name);
    }

    public compareLevel(): number {
        return parseFloat(this.m_iLevel + "");
    }
    public compareId(): number {
        return parseInt(this.id + "");
    }
}
