    /**
     * 获取货币列表
     * @param chainId 链id
     * @param currTab 链id
     * @returns
     */
    public getTokensByChainId(chainId: number, currTab: number): CurrencyAddressItem[] {
        const m_dicCurrencyAddress: Dictionary = SheetDataManager._instance.m_dicCurrencyAddress;
        const value = m_dicCurrencyAddress.values;
        var tokens = [];
        for (let i: number = 0; i < value.length; i++) {
            var currencyAddressItem: CurrencyAddressItem = value[i];
            if (currTab == 1) {
                //充值
                if (
                    GameSetting.vType == currencyAddressItem.isSN &&
                    1 == currencyAddressItem.openRecharge &&
                    chainId == currencyAddressItem.chainId
                ) {
                    tokens.push(currencyAddressItem);
                }
            } else if (currTab == 2) {
                //提币
                if (GameSetting.vType == currencyAddressItem.isSN && 1 == currencyAddressItem.openExtract && chainId == currencyAddressItem.chainId) {
                    tokens.push(currencyAddressItem);
                }
            }
        }
        return tokens;
    }

