const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import { ModuleManager } from "../../common/ModuleManager";
import { PlayerDto } from "../../data/dto/PlayerDto";
import { ModuleName } from "../../global/ModuleName";
import { com } from "../../network/pb/socket";
import { NewPlayerIconBase } from "./NewPlayerIcon.generated";

@regClass('onBubzG/TXiStu5YetXWSQ==')
export class NewPlayerIcon extends NewPlayerIconBase {
    public playerDto: com.snake.socket.RankObject;
    public roleId: string;
    public showAdd: boolean = false;
    private isAddEvent: boolean = false;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.addEvent();
    }

    private addEvent() {
        if (!this.isAddEvent) {
            this.on(Laya.Event.CLICK, this, this.toDetail);
            this.isAddEvent = true;
        }
    }

    public set dataSource(value: any) {
        super.dataSource = value;
        this.playerDto = value as com.snake.socket.RankObject;
        if (!this.playerDto) {
            return;
        }

        this.setCurrentOutPut();
    }

    public set headSkin(headId: any) {
        if (parseInt(headId) > 0) {
            this.img_head.skin = GameResourceManager.getPlayerIcon(headId);
        } else {
            this.setImage(headId);
        }

    }

    public setHeadSkinAndRoldId(headId: any, _roleId: string) {
        if (parseInt(headId) > 0) {
            this.img_head.skin = GameResourceManager.getPlayerIcon(headId);
        } else {
            this.setImage(headId);
        }
        this.roleId = _roleId;
    }

    async setCurrentOutPut() {
        if (!this.playerDto) return;
        this.roleId = this.playerDto.roleId;
        let headId = this.playerDto.icon;
        if (parseInt(headId) > 0) {
            this.img_head.skin = GameResourceManager.getPlayerIcon(headId);
        } else {
            this.setImage(headId);
        }
    }

    /**
     * 设置图片链接并加载图片
     * @param url
     */
    setImage(url: any) {
        // 清理当前的Image对象纹理
        this.clearImage();
        var that = this;
        // 加载图片资源
        Laya.loader.load(
            url,
            Laya.Handler.create(this, () => {
                if (that.destroyed) {
                    return;
                }
                this.img_head.skin = url;
            }),
            null,
            Laya.Loader.IMAGE,
            -1,
            true,
            "1111",
            false,
            false
        );
    }

    /**
     * 清理当前的Image对象纹理
     */
    clearImage() {
        if (this.img_head) {
            this.img_head.texture = null;
        }
    }

    /**
     * 销毁组件
     * @param destroyChild
     */
    destroy(destroyChild = true) {
        // 清理Image对象的纹理
        this.clearImage();
        // 调用父类的销毁方法
        super.destroy(destroyChild);
    }

    private toDetail() {
        console.log("toDetail");

        var roleId = this.roleId;
        if (roleId) ModuleManager.intance.openModule(ModuleName.RoleInfoDialog, roleId);
    }
}
