import { Point } from "./Point";
import { Vec2 } from "./Vec2";

/**
 * 数学工具类
 */
export class MathUtil {
    public static readonly PI2 = Math.PI * 2;

    public static clamp(value: number, min: number, max: number): number {
        return Math.max(min, Math.min(max, value));
    }

    public static lerp(start: number, end: number, t: number): number {
        return start + (end - start) * t;
    }

    public static angleToRadian(angle: number): number {
        return (angle * Math.PI) / 180;
    }

    public static radianToAngle(radian: number): number {
        return (radian * 180) / Math.PI;
    }

    public static randomRange(min: number, max: number): number {
        return min + Math.random() * (max - min);
    }

    public static randomInt(min: number, max: number): number {
        return Math.floor(this.randomRange(min, max + 1));
    }

    public static getDistance(p1: Point, p2: Point): number {
        const dx = p1.x - p2.x;
        const dy = p1.y - p2.y;
        return Math.sqrt(dx * dx + dy * dy);
    }
    public static getVecDistance(p1: Vec2, p2: Vec2): number {
        const dx = p1.x - p2.x;
        const dy = p1.y - p2.y;
        return Math.sqrt(dx * dx + dy * dy);
    }
    public static distance(x1: number, y1: number, x2: number, y2: number): number {
        const dx = x1 - x2;
        const dy = y1 - y2;
        return Math.sqrt(dx * dx + dy * dy);
    }
    public static getAngle(p1: Point, p2: Point): number {
        return Math.atan2(p2.y - p1.y, p2.x - p1.x);
    }
}
