const { regClass } = Laya;
import { LayerManager } from "../../common/LayerManager";
import { ItemVo } from "../../data/vo/pack/ItemVo";
import { RewardGetDialogBase } from "./RewardGetDialog.generated";
import SoundMgr from "../../common/SoundMgr";

@regClass('xwYUFnd4S3uJGIJSjjbRag==')
export class RewardGetDialog extends RewardGetDialogBase {
    public m_strName: string = "我是OpenSceneRuntime";
    public m_iLayerType: number = LayerManager.M_POP;
    public m_iPositionType: number = LayerManager.CENTER;
    private reward: any[];

    public constructor(_data: any) {
        super();
    }

    onEnable(): void {
        SoundMgr.playSoundByName(SoundMgr.soundName32);
    }

    public setOpenData(_data: any) {
        if (_data) {
            this.reward = _data;
        }
        var items: ItemVo[] = [];
        var itemDtos: any[] = this.reward;
        itemDtos.forEach((itemDto) => {
            if (itemDto.itemId && itemDto.itemId > 0) {
                var itemVo = new ItemVo(itemDto.itemId);
                itemVo.newAddCnt = itemDto.num;
                if (itemDto.itemId == 3011) {
                    itemVo.itemItem.icon = itemDto.itemId;
                }
                items.push(itemVo);
            }
        });
        var spaceX = this.list_reward.spaceX;
        var itemRenderW = (this.list_reward as any).itemTemplate.width;

        var len: number = items.length;
        this.list_reward.repeatX = len;
        var listW: number = len * itemRenderW + spaceX * (len - 1);

        this.list_reward.width = listW;
        this.list_reward.x = (this.width - listW) >> 1;

        this.list_reward.array = items;
    }
}
